from collections import deque, defaultdict
# Source objects occupy the top area; each color maps to one matching band.
bands={6:(14,18,7),4:(20,23,6),7:(25,28,1)}
# Identify 4-connected components by color in rows 0..13.
H,W=14,24
seen=set(); comps=defaultdict(list)
for r in range(H):
    for c in range(W):
        col=grid[r][c]
        if col==9 or (r,c) in seen: continue
        q=deque([(r,c)]); seen.add((r,c)); pts=[]
        while q:
            rr,cc=q.popleft(); pts.append((rr,cc))
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                nr,nc=rr+dr,cc+dc
                if 0<=nr<H and 0<=nc<W and (nr,nc) not in seen and grid[nr][nc]==col:
                    seen.add((nr,nc)); q.append((nr,nc))
        comps[col].append(pts)
print({col:[(min(r for r,c in p),max(r for r,c in p),min(c for r,c in p),max(c for r,c in p),len(p)) for p in ps] for col,ps in comps.items()})
corrected=[row[:] for row in grid]
# Clear the source motifs back to the background.
for r in range(H):
    for c in range(W):
        if grid[r][c]!=9: corrected[r][c]=9
# Copy every color component into its matching band; color pixels become the side color,
# all other cells inside its bounding box become the band's background color.
for col, component_list in comps.items():
    top,bottom,side=bands[col]
    for pts in component_list:
        r0=min(r for r,c in pts); r1=max(r for r,c in pts)
        c0=min(c for r,c in pts); c1=max(c for r,c in pts)
        target_top=bottom-(r1-r0)
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
                corrected[target_top+(r-r0)][c]=side if grid[r][c]==col else col
print('\n'.join(' '.join(map(str,row)) for row in corrected))
